#include "batch_norm_activation.cuh"
#include <cuda_runtime.h>
#include <cmath>
#include <cstdlib>
int main(){constexpr std::size_t N=7;float hb[N]={-2,-.5f,0,.5f,2,-3,4},hs[N]={1,1,-1,-1,-3,4,-5},hg[N]={1,2,3,4,5,6,7};float *b,*s,*g,*db,*ds;if(cudaMalloc(&b,N*4)!=cudaSuccess||cudaMalloc(&s,N*4)!=cudaSuccess||cudaMalloc(&g,N*4)!=cudaSuccess||cudaMalloc(&db,N*4)!=cudaSuccess||cudaMalloc(&ds,N*4)!=cudaSuccess)return 1;cudaMemcpy(b,hb,N*4,cudaMemcpyHostToDevice);cudaMemcpy(s,hs,N*4,cudaMemcpyHostToDevice);cudaMemcpy(g,hg,N*4,cudaMemcpyHostToDevice);if(mgt_cuda::LaunchBatchNormResidualReluForward(s,b,N,0)!=mgt::Status::kOk||mgt_cuda::LaunchBatchNormResidualReluBackward(b,g,db,ds,N,0)!=mgt::Status::kOk||cudaDeviceSynchronize()!=cudaSuccess)return 1;float o[N],gb[N],gs[N];cudaMemcpy(o,b,N*4,cudaMemcpyDeviceToHost);cudaMemcpy(gb,db,N*4,cudaMemcpyDeviceToHost);cudaMemcpy(gs,ds,N*4,cudaMemcpyDeviceToHost);for(std::size_t i=0;i<N;i++){float z=hb[i]+hs[i],e=z>0?z:0,d=e>0?hg[i]:0;if(std::fabs(o[i]-e)>1e-7f||std::fabs(gb[i]-d)>1e-7f||std::fabs(gs[i]-d)>1e-7f)return 1;}cudaMemcpy(b,hb,N*4,cudaMemcpyHostToDevice);if(mgt_cuda::LaunchBatchNormReluForward(b,N,0)!=mgt::Status::kOk||mgt_cuda::LaunchBatchNormReluBackward(b,g,db,N,0)!=mgt::Status::kOk||cudaDeviceSynchronize()!=cudaSuccess)return 1;cudaMemcpy(o,b,N*4,cudaMemcpyDeviceToHost);cudaMemcpy(gb,db,N*4,cudaMemcpyDeviceToHost);for(std::size_t i=0;i<N;i++){float e=hb[i]>0?hb[i]:0,d=e>0?hg[i]:0;if(std::fabs(o[i]-e)>1e-7f||std::fabs(gb[i]-d)>1e-7f)return 1;}return 0;}